SELECT id, message_key AS messageKey, knowledge_base_id AS knowledgeBaseId, document_id AS documentId, chunk_id AS chunkId, rank_no AS rankNo, score, rerank_score AS rerankScore, quote_text AS quoteText, created_at AS createdAt FROM message_retrieval_source WHERE message_key IN
#{messageKey}
ORDER BY message_key ASC, rank_no ASC
